# ============================================================
# VISIONINSPECT AI
# DATASET DISTRIBUTION REPORT V2
# ============================================================
#
# Reads the manifests generated by split_v2.py and produces:
#
#   1. Category distribution
#   2. Train / validation / test distribution
#   3. Normal / defective test distribution
#   4. Defect-type distribution
#   5. Class imbalance analysis
#   6. Dataset sanity checks
#
# IMPORTANT:
#   This script DOES NOT modify the dataset.
#
# ============================================================

from __future__ import annotations

import json
from collections import Counter, defaultdict
from pathlib import Path


# ============================================================
# PATHS
# ============================================================

BASE_DIR = Path(__file__).resolve().parent

MANIFEST_DIR = (
    BASE_DIR
    / "evaluation"
    / "manifests"
)

CATEGORY_MANIFEST = (
    MANIFEST_DIR
    / "category_manifest_v2.json"
)

ANOMALY_MANIFEST = (
    MANIFEST_DIR
    / "anomaly_manifest_v2.json"
)

REPORT_DIR = (
    BASE_DIR
    / "evaluation"
    / "reports"
)

REPORT_FILE = (
    REPORT_DIR
    / "dataset_distribution_v2.json"
)


# ============================================================
# LOAD JSON
# ============================================================

def load_json(path: Path):

    if not path.exists():

        raise FileNotFoundError(
            f"Manifest not found:\n{path}\n\n"
            "Run split_v2.py first."
        )

    with path.open(
        "r",
        encoding="utf-8",
    ) as file:

        return json.load(file)


# ============================================================
# CATEGORY COUNTS
# ============================================================

def count_by_category(items):

    counts = Counter()

    for item in items:

        category = item.get(
            "category",
            "Unknown",
        )

        counts[category] += 1

    return counts


# ============================================================
# DEFECT TYPE COUNTS
# ============================================================

def count_defect_types(items):

    counts = Counter()

    for item in items:

        defect_type = item.get(
            "defect_type"
        )

        if defect_type:

            counts[defect_type] += 1

    return counts


# ============================================================
# TEST NORMAL / DEFECTIVE COUNTS
# ============================================================

def count_test_labels(items):

    normal = 0
    defective = 0

    for item in items:

        label = item.get(
            "label_name",
            ""
        ).lower()

        if label == "normal":

            normal += 1

        elif label == "defective":

            defective += 1

    return normal, defective


# ============================================================
# CATEGORY MATRIX
# ============================================================

def build_category_matrix(
    train,
    validation,
    test,
    categories,
):

    train_counts = count_by_category(
        train
    )

    val_counts = count_by_category(
        validation
    )

    test_counts = count_by_category(
        test
    )

    matrix = []

    for category in categories:

        matrix.append({

            "category": category,

            "train": train_counts.get(
                category,
                0,
            ),

            "validation": val_counts.get(
                category,
                0,
            ),

            "test": test_counts.get(
                category,
                0,
            ),

            "total": (
                train_counts.get(
                    category,
                    0,
                )
                +
                val_counts.get(
                    category,
                    0,
                )
                +
                test_counts.get(
                    category,
                    0,
                )
            ),
        })

    return matrix


# ============================================================
# MIN / MAX ANALYSIS
# ============================================================

def distribution_stats(
    values
):

    if not values:

        return {
            "min": 0,
            "max": 0,
            "average": 0,
            "range": 0,
        }

    minimum = min(values)
    maximum = max(values)

    average = (
        sum(values)
        / len(values)
    )

    return {

        "min": minimum,

        "max": maximum,

        "average": round(
            average,
            2,
        ),

        "range": (
            maximum
            - minimum
        ),
    }


# ============================================================
# PRINT CATEGORY TABLE
# ============================================================

def print_category_table(
    matrix
):

    print()

    print(
        f"{'Category':<15}"
        f"{'Train':>10}"
        f"{'Val':>10}"
        f"{'Test':>10}"
        f"{'Total':>10}"
    )

    print("-" * 55)

    for item in matrix:

        print(
            f"{item['category']:<15}"
            f"{item['train']:>10}"
            f"{item['validation']:>10}"
            f"{item['test']:>10}"
            f"{item['total']:>10}"
        )

    print("-" * 55)

    total_train = sum(
        item["train"]
        for item in matrix
    )

    total_val = sum(
        item["validation"]
        for item in matrix
    )

    total_test = sum(
        item["test"]
        for item in matrix
    )

    total = (
        total_train
        + total_val
        + total_test
    )

    print(
        f"{'TOTAL':<15}"
        f"{total_train:>10}"
        f"{total_val:>10}"
        f"{total_test:>10}"
        f"{total:>10}"
    )


# ============================================================
# PRINT DEFECT TABLE
# ============================================================

def print_defect_table(
    test_items
):

    category_defects = defaultdict(
        Counter
    )

    for item in test_items:

        category = item.get(
            "category",
            "Unknown",
        )

        defect_type = item.get(
            "defect_type"
        )

        if defect_type:

            category_defects[
                category
            ][defect_type] += 1

    print()

    print(
        "TEST DEFECT DISTRIBUTION"
    )

    print("=" * 70)

    for category in sorted(
        category_defects
    ):

        print(
            f"\n{category}:"
        )

        for defect_type, count in (
            sorted(
                category_defects[
                    category
                ].items()
            )
        ):

            print(
                f"    "
                f"{defect_type:<30}"
                f"{count:>6}"
            )


# ============================================================
# LEAKAGE CHECK
# ============================================================

def check_overlap(
    train,
    validation,
    test,
):

    train_paths = {
        item["image_path"]
        for item in train
    }

    val_paths = {
        item["image_path"]
        for item in validation
    }

    test_paths = {
        item["image_path"]
        for item in test
    }

    train_val = (
        train_paths
        & val_paths
    )

    train_test = (
        train_paths
        & test_paths
    )

    val_test = (
        val_paths
        & test_paths
    )

    return {

        "train_validation_overlap":
            len(train_val),

        "train_test_overlap":
            len(train_test),

        "validation_test_overlap":
            len(val_test),

        "passed":
            not (
                train_val
                or train_test
                or val_test
            ),
    }


# ============================================================
# FILE EXISTENCE CHECK
# ============================================================

def check_files(
    items
):

    missing = []

    for item in items:

        path = Path(
            item["image_path"]
        )

        if not path.exists():

            missing.append(
                str(path)
            )

    return missing


# ============================================================
# MAIN
# ============================================================

def main():

    print()
    print("=" * 70)
    print(
        "VISIONINSPECT AI"
    )
    print(
        "DATASET DISTRIBUTION REPORT V2"
    )
    print("=" * 70)

    # --------------------------------------------------------
    # LOAD MANIFESTS
    # --------------------------------------------------------

    category_manifest = load_json(
        CATEGORY_MANIFEST
    )

    anomaly_manifest = load_json(
        ANOMALY_MANIFEST
    )

    # --------------------------------------------------------
    # CATEGORY DATA
    # --------------------------------------------------------

    category_train = (
        category_manifest.get(
            "train",
            []
        )
    )

    category_val = (
        category_manifest.get(
            "validation",
            []
        )
    )

    category_test = (
        category_manifest.get(
            "test",
            []
        )
    )

    categories = (
        category_manifest.get(
            "categories",
            []
        )
    )

    # --------------------------------------------------------
    # ANOMALY DATA
    # --------------------------------------------------------

    anomaly_train = (
        anomaly_manifest.get(
            "train",
            []
        )
    )

    anomaly_val = (
        anomaly_manifest.get(
            "validation",
            []
        )
    )

    anomaly_test = (
        anomaly_manifest.get(
            "test",
            []
        )
    )

    # ========================================================
    # CATEGORY DISTRIBUTION
    # ========================================================

    matrix = build_category_matrix(
        category_train,
        category_val,
        category_test,
        categories,
    )

    print()

    print(
        "CATEGORY DISTRIBUTION"
    )

    print("=" * 70)

    print_category_table(
        matrix
    )

    # ========================================================
    # ANOMALY DISTRIBUTION
    # ========================================================

    normal_test, defective_test = (
        count_test_labels(
            anomaly_test
        )
    )

    print()

    print(
        "ANOMALY TEST DISTRIBUTION"
    )

    print("=" * 70)

    print(
        f"Normal test images    : "
        f"{normal_test}"
    )

    print(
        f"Defective test images : "
        f"{defective_test}"
    )

    print(
        f"Total test images     : "
        f"{len(anomaly_test)}"
    )

    # ========================================================
    # DEFECT TYPES
    # ========================================================

    defect_counts = (
        count_defect_types(
            anomaly_test
        )
    )

    print()

    print(
        "GLOBAL DEFECT-TYPE DISTRIBUTION"
    )

    print("=" * 70)

    for defect_type, count in sorted(
        defect_counts.items()
    ):

        print(
            f"{defect_type:<35}"
            f"{count:>8}"
        )

    # ========================================================
    # CATEGORY DEFECT DETAILS
    # ========================================================

    print_defect_table(
        anomaly_test
    )

    # ========================================================
    # DISTRIBUTION STATISTICS
    # ========================================================

    train_values = [
        item["train"]
        for item in matrix
    ]

    val_values = [
        item["validation"]
        for item in matrix
    ]

    test_values = [
        item["test"]
        for item in matrix
    ]

    train_stats = distribution_stats(
        train_values
    )

    val_stats = distribution_stats(
        val_values
    )

    test_stats = distribution_stats(
        test_values
    )

    print()

    print(
        "CATEGORY BALANCE ANALYSIS"
    )

    print("=" * 70)

    print(
        "Training:"
    )

    print(
        f"    Min     : "
        f"{train_stats['min']}"
    )

    print(
        f"    Max     : "
        f"{train_stats['max']}"
    )

    print(
        f"    Average : "
        f"{train_stats['average']}"
    )

    print(
        f"    Range   : "
        f"{train_stats['range']}"
    )

    print()

    print(
        "Validation:"
    )

    print(
        f"    Min     : "
        f"{val_stats['min']}"
    )

    print(
        f"    Max     : "
        f"{val_stats['max']}"
    )

    print(
        f"    Average : "
        f"{val_stats['average']}"
    )

    print(
        f"    Range   : "
        f"{val_stats['range']}"
    )

    print()

    print(
        "Test:"
    )

    print(
        f"    Min     : "
        f"{test_stats['min']}"
    )

    print(
        f"    Max     : "
        f"{test_stats['max']}"
    )

    print(
        f"    Average : "
        f"{test_stats['average']}"
    )

    print(
        f"    Range   : "
        f"{test_stats['range']}"
    )

    # ========================================================
    # LEAKAGE CHECK
    # ========================================================

    category_leakage = check_overlap(
        category_train,
        category_val,
        category_test,
    )

    anomaly_leakage = check_overlap(
        anomaly_train,
        anomaly_val,
        anomaly_test,
    )

    print()

    print(
        "LEAKAGE CHECK"
    )

    print("=" * 70)

    print(
        "Category manifests:"
    )

    print(
        f"    Train/Validation : "
        f"{category_leakage['train_validation_overlap']}"
    )

    print(
        f"    Train/Test       : "
        f"{category_leakage['train_test_overlap']}"
    )

    print(
        f"    Validation/Test  : "
        f"{category_leakage['validation_test_overlap']}"
    )

    print(
        f"    Result           : "
        f"{'PASS' if category_leakage['passed'] else 'FAIL'}"
    )

    print()

    print(
        "Anomaly manifests:"
    )

    print(
        f"    Train/Validation : "
        f"{anomaly_leakage['train_validation_overlap']}"
    )

    print(
        f"    Train/Test       : "
        f"{anomaly_leakage['train_test_overlap']}"
    )

    print(
        f"    Validation/Test  : "
        f"{anomaly_leakage['validation_test_overlap']}"
    )

    print(
        f"    Result           : "
        f"{'PASS' if anomaly_leakage['passed'] else 'FAIL'}"
    )

    # ========================================================
    # MISSING FILE CHECK
    # ========================================================

    category_all = (
        category_train
        + category_val
        + category_test
    )

    missing_category_files = (
        check_files(
            category_all
        )
    )

    print()

    print(
        "FILE EXISTENCE CHECK"
    )

    print("=" * 70)

    print(
        f"Category missing files : "
        f"{len(missing_category_files)}"
    )

    if missing_category_files:

        for path in (
            missing_category_files[:20]
        ):

            print(
                f"    {path}"
            )

    # ========================================================
    # BUILD JSON REPORT
    # ========================================================

    report = {

        "dataset": "MVTec AD",

        "seed": category_manifest.get(
            "seed"
        ),

        "categories": categories,

        "counts": {

            "train": len(
                category_train
            ),

            "validation": len(
                category_val
            ),

            "official_test": len(
                category_test
            ),

            "total": (
                len(category_train)
                + len(category_val)
                + len(category_test)
            ),
        },

        "category_distribution": matrix,

        "anomaly_test_distribution": {

            "normal": normal_test,

            "defective": defective_test,

            "total": len(
                anomaly_test
            ),
        },

        "defect_type_distribution": (
            dict(
                sorted(
                    defect_counts.items()
                )
            )
        ),

        "balance_analysis": {

            "train": train_stats,

            "validation": val_stats,

            "test": test_stats,
        },

        "leakage_check": {

            "category": (
                category_leakage
            ),

            "anomaly": (
                anomaly_leakage
            ),
        },

        "missing_files": (
            len(
                missing_category_files
            )
        ),
    }

    # ========================================================
    # SAVE REPORT
    # ========================================================

    REPORT_DIR.mkdir(
        parents=True,
        exist_ok=True,
    )

    with REPORT_FILE.open(
        "w",
        encoding="utf-8",
    ) as file:

        json.dump(
            report,
            file,
            indent=2,
        )

    # ========================================================
    # FINAL RESULT
    # ========================================================

    print()

    print("=" * 70)

    print(
        "DATASET REPORT COMPLETED"
    )

    print("=" * 70)

    print(
        f"Report saved to:"
    )

    print(
        REPORT_FILE
    )

    print()

    if (
        category_leakage["passed"]
        and anomaly_leakage["passed"]
        and not missing_category_files
    ):

        print(
            "OVERALL DATASET SANITY: PASS"
        )

    else:

        print(
            "OVERALL DATASET SANITY: REVIEW REQUIRED"
        )

    print()


if __name__ == "__main__":

    main()